/**
 * Starter characters in the house style. They are generated by one template so
 * proportions, pivots and face anchors are consistent; the result is plain
 * CharacterAsset JSON (exactly what the LLM asset maker writes).
 *
 * Design space: 300 × 600 box, feet at (150, 600), facing right (3/4 view:
 * the face sits on the right half of the head, the ear on the left).
 */
import type { CharacterAsset, Part, Shape } from "../types";
import { PALETTE } from "../styleGuide";
import { pen, type Pt, type Xf } from "../path";

const INK = PALETTE.ink;
const SW = 3;

export function shade(hex: string, k: number): string {
  const m = /^#([0-9a-f]{6})$/i.exec(hex);
  if (!m) return hex;
  const n = parseInt(m[1], 16);
  const c = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => Math.max(0, Math.min(255, Math.round(v * k))));
  return "#" + c.map((v) => v.toString(16).padStart(2, "0")).join("");
}

type TopStyle = "tshirt" | "shirt" | "kameez" | "panjabi" | "saree" | "frock" | "kurti";
type BottomStyle = "pants" | "shorts" | "salwar" | "bare";
type HairStyle = "short" | "side_part" | "long" | "bun" | "bald_white" | "kid_short" | "pigtails" | "bun_grey";

export interface CharacterSpec {
  id: string;
  label: string;
  tags: string[];
  skin: string;
  hair: string;
  hairStyle: HairStyle;
  top: TopStyle;
  topColor: string;
  topColor2?: string;
  sleeve: "short" | "long" | "3q";
  bottom: BottomStyle;
  bottomColor: string;
  shoe: string;
  /** Overall height factor (1 = adult). */
  height?: number;
  /** Extra head scale (children have bigger heads). */
  headScale?: number;
  /** Body width factor (belly). */
  girth?: number;
  beard?: string;
  moustache?: string;
  glasses?: boolean;
  cap?: string;
}

const s = (fill: string, d: string, stroke = true, opacity?: number): Shape => ({
  d,
  fill,
  ...(stroke ? { stroke: INK, strokeWidth: SW } : {}),
  ...(opacity !== undefined ? { opacity } : {}),
});
const line = (d: string, w = 2.5): Shape => ({ d, fill: "none", stroke: INK, strokeWidth: w });

export function buildCharacter(c: CharacterSpec): CharacterAsset {
  const H = c.height ?? 1;
  const HS = c.headScale ?? 1;
  const G = c.girth ?? 1;
  const neck: Pt = [154, 162];
  // body transform (scale around the feet), head transform (extra scale around the neck)
  const TB: Xf = ([x, y]) => [150 + (x - 150) * H, 600 - (600 - y) * H];
  const nB = TB(neck);
  const TH: Xf = ([x, y]) => [nB[0] + (x - neck[0]) * H * HS, nB[1] + (y - neck[1]) * H * HS];
  // girth widens the torso around x=152
  const TG: Xf = ([x, y]) => TB([152 + (x - 152) * G, y]);
  const B = pen(TB);
  const BG = pen(TG);
  const Hd = pen(TH);
  const skin = c.skin;
  const skinD = shade(skin, 0.86);
  const top = c.topColor;
  const top2 = c.topColor2 ?? shade(top, 0.8);
  const longTop = c.top === "kameez" || c.top === "panjabi" || c.top === "saree" || c.top === "kurti";

  /* ---- body ---- */
  const body: Shape[] = [s(skin, B.rrect(140, 136, 28, 44, 8))];
  switch (c.top) {
    case "tshirt":
      body.push(s(top, BG.rrect(104, 166, 96, 226, 24)));
      body.push(line(B.curve([[138, 168], [154, 186], [170, 168]])));
      body.push(s(shade(top, 0.85), BG.rect(106, 372, 92, 18), false));
      break;
    case "shirt":
      body.push(s(top, BG.rrect(104, 166, 96, 220, 22)));
      body.push(s(shade(top, 0.9), B.poly([[136, 164], [154, 192], [146, 200], [130, 172]])));
      body.push(s(shade(top, 0.9), B.poly([[172, 164], [154, 192], [162, 200], [178, 172]])));
      body.push(line(B.line([154, 196], [154, 372]), 2));
      body.push(s(shade(top, 0.88), B.rrect(166, 222, 22, 22, 4)));
      body.push(s("#3b2a22", BG.rect(104, 372, 96, 16)));
      body.push(s("#d9b44a", B.rect(160, 374, 12, 12), false));
      break;
    case "kameez":
    case "kurti":
      body.push(
        s(top, BG.poly([[112, 166], [192, 166], [202, 186], [204, 300], [218, c.top === "kurti" ? 440 : 486], [86, c.top === "kurti" ? 440 : 486], [100, 300], [102, 186]])),
      );
      body.push(s(top2, BG.poly([[88, c.top === "kurti" ? 426 : 470], [216, c.top === "kurti" ? 426 : 470], [218, c.top === "kurti" ? 440 : 486], [86, c.top === "kurti" ? 440 : 486]])));
      body.push(line(B.curve([[140, 168], [154, 190], [168, 168]])));
      if (c.top === "kameez") {
        // orna (dupatta) across the chest
        body.push(s(top2, BG.poly([[176, 164], [200, 176], [118, 330], [100, 312]])));
      }
      break;
    case "panjabi":
      body.push(s(top, BG.poly([[110, 166], [194, 166], [204, 188], [206, 476], [98, 476], [100, 188]])));
      body.push(line(B.line([156, 172], [156, 268]), 2));
      for (const y of [196, 222, 248]) body.push(s(top2, B.ellipse(162, y, 3.5, 3.5)));
      body.push(line(B.curve([[140, 166], [154, 176], [168, 166]])));
      break;
    case "saree":
      body.push(s(top2, BG.rrect(108, 166, 88, 100, 20)));
      body.push(s(top, BG.poly([[106, 248], [198, 248], [214, 588], [90, 588]])));
      body.push(s(top2, BG.poly([[91, 566], [213, 566], [214, 588], [90, 588]]), false));
      // pleats
      body.push(line(B.line([168, 300], [178, 562]), 2));
      body.push(line(B.line([156, 300], [160, 562]), 2));
      // achol over the shoulder and chest
      body.push(s(top, BG.poly([[104, 176], [124, 164], [198, 290], [204, 360], [178, 364], [104, 236]])));
      body.push(s(top2, BG.poly([[178, 352], [204, 348], [204, 364], [178, 366]]), false));
      break;
    case "frock":
      body.push(s(top, BG.rrect(110, 170, 84, 110, 18)));
      body.push(s(top, BG.poly([[112, 262], [192, 262], [222, 430], [82, 430]])));
      body.push(s(top2, BG.poly([[85, 414], [219, 414], [222, 430], [82, 430]]), false));
      body.push(s(top2, BG.rect(110, 254, 84, 14)));
      break;
  }

  /* ---- legs ---- */
  const leg = (cx: number): Shape[] => {
    const out: Shape[] = [];
    const shoe = s(c.shoe, B.ellipse(cx + 8, 588, 22, 11));
    if (c.bottom === "pants") out.push(s(c.bottomColor, B.rrect(cx - 16, 376, 32, 202, 12)));
    else if (c.bottom === "salwar") {
      out.push(s(c.bottomColor, B.rrect(cx - 18, 376, 36, 198, 16)));
      out.push(s(shade(c.bottomColor, 0.9), B.rrect(cx - 13, 560, 26, 16, 5)));
    } else if (c.bottom === "shorts") {
      out.push(s(skin, B.rrect(cx - 11, 430, 22, 148, 10)));
      out.push(s(c.bottomColor, B.rrect(cx - 18, 376, 36, 84, 10)));
    } else out.push(s(skin, B.rrect(cx - 11, 390, 22, 188, 10)));
    out.push(shoe);
    return out;
  };
  const legL = leg(138).map((x) => (x.fill === skin ? { ...x, fill: skinD } : x.fill === c.bottomColor ? { ...x, fill: shade(c.bottomColor, 0.88) } : x));
  const legR = leg(166);

  /* ---- arms ---- */
  const arm = (cx: number, far: boolean): Shape[] => {
    const sk = far ? skinD : skin;
    const cl = far ? shade(top, 0.86) : top;
    const sleeveLen = c.sleeve === "long" ? 186 : c.sleeve === "3q" ? 134 : 82;
    const out: Shape[] = [s(sk, B.rrect(cx - 12, 182, 24, 192, 11))];
    out.push(s(cl, B.rrect(cx - 16, 168, 32, sleeveLen + 10, 15)));
    if (c.sleeve === "long" && (c.top === "shirt" || c.top === "panjabi")) out.push(s(shade(cl, 0.9), B.rrect(cx - 15, 346, 30, 14, 5)));
    out.push(s(sk, B.ellipse(cx, 378, 13.5, 14)));
    return out;
  };

  /* ---- head ---- */
  const head: Shape[] = [
    s(skin, Hd.ellipse(118, 104, 9, 13)),
    s(skin, Hd.ellipse(156, 96, 46, 54)),
    s(skinD, Hd.ellipse(118, 104, 4, 6), false),
  ];
  if (c.moustache) head.push(s(c.moustache, Hd.blob([[152, 118], [168, 113], [186, 117], [184, 122], [168, 120], [154, 124]])));

  /* ---- hair ---- */
  const hair: Shape[] = [];
  const hairBack: Shape[] = [];
  const hc = c.hair;
  switch (c.hairStyle) {
    case "short":
      hair.push(s(hc, Hd.blob([[106, 116], [104, 70], [122, 42], [160, 32], [196, 44], [210, 74], [198, 80], [178, 62], [146, 64], [128, 82], [126, 116]])));
      break;
    case "side_part":
      hair.push(s(hc, Hd.blob([[106, 118], [102, 72], [120, 40], [160, 30], [200, 42], [212, 70], [204, 78], [186, 58], [160, 66], [136, 70], [126, 88], [126, 118]])));
      hair.push(s(shade(hc, 1.6), Hd.blob([[110, 112], [108, 96], [118, 96], [118, 112]]), false, 0.8));
      break;
    case "kid_short":
      hair.push(s(hc, Hd.blob([[106, 112], [104, 66], [126, 40], [162, 34], [196, 46], [210, 76], [200, 76], [190, 62], [176, 72], [164, 60], [146, 70], [128, 84], [124, 112]])));
      break;
    case "long":
      hairBack.push(s(hc, Hd.blob([[100, 70], [132, 40], [182, 40], [208, 74], [206, 140], [184, 150], [140, 210], [116, 290], [94, 270], [92, 150]])));
      hair.push(s(hc, Hd.blob([[106, 112], [104, 68], [126, 40], [162, 32], [198, 44], [212, 76], [206, 96], [190, 66], [158, 58], [134, 72], [124, 100], [124, 120]])));
      break;
    case "pigtails":
      hairBack.push(s(hc, Hd.ellipse(98, 120, 16, 30)));
      hairBack.push(s(hc, Hd.ellipse(100, 160, 13, 22)));
      hair.push(s(hc, Hd.blob([[106, 112], [104, 66], [126, 40], [162, 32], [198, 44], [212, 80], [202, 84], [186, 64], [160, 60], [136, 72], [124, 98], [124, 116]])));
      hair.push(s(PALETTE.cloth[0], Hd.ellipse(106, 96, 7, 7)));
      break;
    case "bun":
    case "bun_grey":
      hairBack.push(s(hc, Hd.ellipse(104, 72, 22, 21)));
      hair.push(s(hc, Hd.blob([[106, 116], [104, 70], [124, 42], [162, 34], [198, 46], [210, 74], [200, 76], [180, 58], [150, 56], [130, 72], [124, 96], [124, 118]])));
      if (c.hairStyle === "bun_grey") hair.push(line(Hd.curve([[130, 50], [160, 42], [186, 50]]), 2));
      break;
    case "bald_white":
      hair.push(s(hc, Hd.blob([[108, 120], [104, 82], [114, 66], [126, 70], [126, 120]])));
      break;
  }
  if (c.beard) {
    hair.push(s(c.beard, Hd.blob([[124, 112], [130, 140], [150, 160], [178, 164], [200, 146], [204, 124], [194, 130], [186, 140], [168, 142], [150, 136], [136, 118]])));
  }
  if (c.cap) hair.push(s(c.cap, Hd.blob([[106, 72], [118, 46], [156, 34], [196, 44], [210, 70], [160, 62]])));

  const parts: Part[] = [
    { name: "arm_l", pivot: TB([124, 186]), z: 0, shapes: arm(124, true), tip: TB([124, 378]) },
    { name: "leg_l", pivot: TB([138, 386]), z: 1, shapes: legL, tip: TB([146, 588]) },
    { name: "leg_r", pivot: TB([166, 386]), z: 1, shapes: legR, tip: TB([174, 588]) },
    { name: "body", pivot: TB([152, 386]), z: 2, shapes: body },
  ];
  if (hairBack.length) parts.push({ name: "hair_back", pivot: nB, z: 3, shapes: hairBack });
  parts.push({ name: "head", pivot: nB, z: 4, shapes: head });
  if (hair.length) parts.push({ name: "hair", pivot: nB, z: 5, shapes: hair });
  if (c.glasses) {
    parts.push({
      name: "accessory",
      pivot: nB,
      z: 6,
      shapes: [
        { d: Hd.ellipse(148, 98, 11, 10), fill: "rgba(255,255,255,0.18)", stroke: INK, strokeWidth: 2.5 },
        { d: Hd.ellipse(181, 98, 11, 10), fill: "rgba(255,255,255,0.18)", stroke: INK, strokeWidth: 2.5 },
        line(Hd.line([159, 97], [170, 97]), 2.5),
        line(Hd.line([137, 96], [120, 92]), 2.5),
      ],
    });
  }
  parts.push({ name: "arm_r", pivot: TB([178, 186]), z: 7, shapes: arm(178, false), tip: TB([178, 378]) });
  // long tops hide the hips: keep legs behind them (they already are by z)
  void longTop;

  const eS = 5.6 * H * HS;
  return {
    kind: "character",
    id: c.id,
    label: c.label,
    tags: c.tags,
    size: [300, 600],
    parts,
    face: {
      eyeL: TH([147, 98]),
      eyeR: TH([180, 98]),
      mouth: TH([168, 128]),
      eyeSize: Math.round(eS * 10) / 10,
      skin,
      ink: INK,
    },
  };
}

