export const STARTER_CHARACTERS: CharacterAsset[] = CHARACTER_SPECS.map(buildCharacter);

/** Swap colours (fills, strokes and face skin) to make a distinct cast member from a library asset. */
export function recolor(asset: CharacterAsset, map: Record<string, string>, newId: string): CharacterAsset {
  const m = new Map(Object.entries(map).map(([k, v]) => [k.toLowerCase(), v]));
  const sw = (c?: string) => (c && m.has(c.toLowerCase()) ? m.get(c.toLowerCase()) : c);
  // derived shades (far limbs) follow their base colour
  for (const [k, v] of [...m]) {
    for (const f of [0.86, 0.88, 0.8, 0.85, 0.9]) {
      const a = shade(k, f).toLowerCase();
      if (!m.has(a) && /^#/.test(v)) m.set(a, shade(v, f));
    }
  }
  const out: CharacterAsset = JSON.parse(JSON.stringify(asset));
  out.id = newId;
  for (const p of out.parts)
    for (const sh of p.shapes) {
      if (sh.fill) sh.fill = sw(sh.fill);
      if (sh.stroke) sh.stroke = sw(sh.stroke);
    }
  out.face.skin = sw(out.face.skin) ?? out.face.skin;
  return out;
}
